import hashlib,json,pathlib
base=pathlib.Path(__file__).resolve().parent; root=base.parents[1]
groups={
'scripts/launch_demo.py':[(1,4,'مكتبات قياسية للبيئة والمسارات والعملية الفرعية والوسائط.'),(6,8,'يحدد جذر المشروع ويعطل جمع إحصاء استخدام المتصفح في Streamlit، ويشغل demo_wizard.py start بوسائط المستخدم ويعيد رمز العملية عبر SystemExit. يتغير متغير البيئة وتبدأ عملية عند التنفيذ أو الاستيراد.')],
'scripts/offline_demo.py':[(1,3,'Path وsubprocess وsys قياسية لتحديد الملفات وتشغيل العمليات.'),(5,9,'يحدد Python في .demo_venv؛ إذا غاب ينفذ setup_offline باستخدام Python الحالي مع check=True، ثم ينفذ launch_demo بالبيئة والوسائط. قد ينشئ بيئة ويشغل خادماً؛ لا يفحص وجود كل اعتماد بمجرد وجود المفسر.')],
'scripts/setup_offline.py':[(1,5,'سلسلة توثيق ومكتبات قياسية للمسار والعملية والوسائط.'),(7,8,'يشغّل wizard بأمر setup و--offline ووسائط المستخدم من الجذر، ويمرر رمز الخروج. قد يثبت حزم محلية؛ لم يشغل هنا.')],
'scripts/verify_environment.py':[(1,1,'يستورد تشخيص البيئة من الحزمة.'),(3,3,'يستدعي التشخيص حتى عند استيراد السكربت؛ يختبر LSTM عشوائياً ويكتب تقرير البيئة كما في الدالة، وليس نتائج مالية.')],
'scripts/bootstrap_cpu.py':[(1,6,'توثيق البحث المحلي عن Python 3.12 x64، واستيرادات البيئة والمسارات والعمليات القياسية.'),(8,11,'يحدد الجذر وسلسلة تحقق لإصدار 3.12 وحجم مؤشر 8 بايت، ويبدأ قائمة المرشحين من XAI_PYTHON إن وجد ثم Python الحالي.'),(12,17,'يبحث في مجلدات uv تحت APPDATA وLOCALAPPDATA وفي UV_PYTHON_INSTALL_DIR عند وجودها عن Python Windows x86_64، ويرتب النتائج تنازلياً.'),(18,23,'يزيل تكرار المرشحين بترتيب الإدراج ويشغل تحقق الإصدار على كل ملف؛ عند النجاح يشغل wizard setup ويعيد رمزه. إن لم يوجد يطبع إرشادات ويخرج 1؛ لا ينزل Python تلقائياً.')],
'scripts/offline_guard/sitecustomize.py':[(1,4,'سلسلة توثق أنه حارس اختبار اختياري؛ os وsocket قياسيتان.'),(6,10,'فقط عند XAI_TEST_OFFLINE=1 يحفظ دوال الاتصال وحل الأسماء الأصلية ويحدد أسماء loopback المقبولة. يحتاج تحميل sitecustomize من مسار Python المناسب.'),(12,14,'_check ترفض host خارج المجموعة بخطأ OSError؛ السماح بالأسماء المحددة لا يثبت حجب كل وسائل الشبكة الممكنة.'),(16,24,'connect وconnect_ex تفحصان عنوان tuple ثم تفوضان الاتصال الأصلي؛ عناوين غير tuple لا يفحصها هذا الشرط.'),(26,32,'getaddrinfo يفحص المضيف ويفوض الأصل ثم يستبدل ثلاث دوال socket داخل العملية. هذا حارس اختبار لواجهات محددة لا جدار حماية شامل.')],
'scripts/verify_preservation_cpu.py':[(1,8,'التوثيق يصف مقارنة الأدلة بمرجع؛ argparse وhashlib وjson وPath قياسية، وROOT أصل المشروع.'),(11,13,'digest تقرأ ملفاً ثنائياً وتحسب SHA-256؛ تعيد بصمة النص الست عشري.'),(16,23,'main تقرأ خيار output الافتراضي وملف baseline ذي البصمات، وتجمع الملفات الناقصة أو المختلفة وتفرض عدم وجود مخالفات. يعتمد الاستنتاج على شمول وموثوقية baseline؛ assert يمكن تعطيله بوضع Python المحسن.'),(24,27,'تكتب إيصال نجاح يتضمن عدد الأدلة وبصمة baseline وأسماء التشغيلات المحمية، وتنشئ مجلد الوجهة وتطبع النجاح؛ هذا الفحص يكتب ملفاً افتراضياً داخل artifacts إذا شُغّل ولم يشغل هنا.'),(30,31,'حارس التنفيذ يستدعي main.')]
}
manifest={}
for path,entries in groups.items():
 raw=(root/path).read_bytes(); src=raw.decode('utf8').splitlines(); digest=hashlib.sha256(raw).hexdigest(); name=path.replace('/','_')+'.md'; out=['# شرح `'+path+'`','',f'بصمة المصدر SHA-256: `{digest}`.','','وصف ثابت؛ لم تُشغّل السكربتات.','']
 for a,b,d in entries: out += [f'## الأسطر {a}–{b}','','```python',*src[a-1:b],'```','',d,'']
 (base/'line_by_line'/name).write_text('\n'.join(out),encoding='utf8'); manifest[path]={'document':'line_by_line/'+name,'ranges':[[a,b] for a,b,_ in entries],'sha256':digest,'review':'يدوية غير مستقلة','quote_verification':'آلي'}
(base/'launch_helpers_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf8')
